arguments.command:
cd /app && python3 -c "
import json,subprocess
r=json.load(open('/tmp/recs.json'))
a=r['input'].upper()
def tm(s):
    return float(subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True).stdout.strip())
def rc(s): return s[::-1].translate(str.maketrans('ACGT','TGCA'))
P=213
fwd={L:(a[P:P+L],tm(a[P:P+L])) for L in range(15,46)}
rev={L:(rc(a[P-L:P]),tm(rc(a[P-L:P]))) for L in range(15,46)}
for L in range(15,46): print(L, round(fwd[L][1],2), round(rev[L][1],2))
"

